mkitem!{mktrait!{# [doc = " `RangeBounds` is implemented by Rust's built-in range types, produced"] # [doc = " by range syntax like `..`, `a..`, `..b`, `..=c`, `d..e`, or `f..=g`."] # [stable (feature = "collections_range" , since = "1.28.0")] # [rustc_diagnostic_item = "RangeBounds"] pub trait RangeBounds < T : ? Sized > { # [doc = " Start index bound."] # [doc = ""] # [doc = " Returns the start value as a `Bound`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::ops::Bound::*;"] # [doc = " use std::ops::RangeBounds;"] # [doc = ""] # [doc = " assert_eq!((..10).start_bound(), Unbounded);"] # [doc = " assert_eq!((3..10).start_bound(), Included(&3));"] # [doc = " ```"] # [stable (feature = "collections_range" , since = "1.28.0")] fn start_bound (& self) -> Bound < & T > ; # [doc = " End index bound."] # [doc = ""] # [doc = " Returns the end value as a `Bound`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::ops::Bound::*;"] # [doc = " use std::ops::RangeBounds;"] # [doc = ""] # [doc = " assert_eq!((3..).end_bound(), Unbounded);"] # [doc = " assert_eq!((3..10).end_bound(), Excluded(&10));"] # [doc = " ```"] # [stable (feature = "collections_range" , since = "1.28.0")] fn end_bound (& self) -> Bound < & T > ; # [doc = " Returns `true` if `item` is contained in the range."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " assert!( (3..5).contains(&4));"] # [doc = " assert!(!(3..5).contains(&2));"] # [doc = ""] # [doc = " assert!( (0.0..1.0).contains(&0.5));"] # [doc = " assert!(!(0.0..1.0).contains(&f32::NAN));"] # [doc = " assert!(!(0.0..f32::NAN).contains(&0.5));"] # [doc = " assert!(!(f32::NAN..1.0).contains(&0.5));"] # [doc = " ```"] # [inline] # [stable (feature = "range_contains" , since = "1.35.0")] fn contains < U > (& self , item : & U) -> bool where T : PartialOrd < U > , U : ? Sized + PartialOrd < T > , { (match self . start_bound () { Included (start) => start <= item , Excluded (start) => start < item , Unbounded => true , }) && (match self . end_bound () { Included (end) => item <= end , Excluded (end) => item < end , Unbounded => true , }) } # [doc = " Returns `true` if the range contains no items."] # [doc = " One-sided ranges (`RangeFrom`, etc) always return `false`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " #![feature(range_bounds_is_empty)]"] # [doc = " use std::ops::RangeBounds;"] # [doc = ""] # [doc = " assert!(!(3..).is_empty());"] # [doc = " assert!(!(..2).is_empty());"] # [doc = " assert!(!RangeBounds::is_empty(&(3..5)));"] # [doc = " assert!( RangeBounds::is_empty(&(3..3)));"] # [doc = " assert!( RangeBounds::is_empty(&(3..2)));"] # [doc = " ```"] # [doc = ""] # [doc = " The range is empty if either side is incomparable:"] # [doc = ""] # [doc = " ```"] # [doc = " #![feature(range_bounds_is_empty)]"] # [doc = " use std::ops::RangeBounds;"] # [doc = ""] # [doc = " assert!(!RangeBounds::is_empty(&(3.0..5.0)));"] # [doc = " assert!( RangeBounds::is_empty(&(3.0..f32::NAN)));"] # [doc = " assert!( RangeBounds::is_empty(&(f32::NAN..5.0)));"] # [doc = " ```"] # [doc = ""] # [doc = " But never empty if either side is unbounded:"] # [doc = ""] # [doc = " ```"] # [doc = " #![feature(range_bounds_is_empty)]"] # [doc = " use std::ops::RangeBounds;"] # [doc = ""] # [doc = " assert!(!(..0).is_empty());"] # [doc = " assert!(!(i32::MAX..).is_empty());"] # [doc = " assert!(!RangeBounds::<u8>::is_empty(&(..)));"] # [doc = " ```"] # [doc = ""] # [doc = " `(Excluded(a), Excluded(b))` is only empty if `a >= b`:"] # [doc = ""] # [doc = " ```"] # [doc = " #![feature(range_bounds_is_empty)]"] # [doc = " use std::ops::Bound::*;"] # [doc = " use std::ops::RangeBounds;"] # [doc = ""] # [doc = " assert!(!(Excluded(1), Excluded(3)).is_empty());"] # [doc = " assert!(!(Excluded(1), Excluded(2)).is_empty());"] # [doc = " assert!( (Excluded(1), Excluded(1)).is_empty());"] # [doc = " assert!( (Excluded(2), Excluded(1)).is_empty());"] # [doc = " assert!( (Excluded(3), Excluded(1)).is_empty());"] # [doc = " ```"] # [unstable (feature = "range_bounds_is_empty" , issue = "137300")] fn is_empty (& self) -> bool where T : PartialOrd , { ! match (self . start_bound () , self . end_bound ()) { (Unbounded , _) | (_ , Unbounded) => true , (Included (start) , Excluded (end)) | (Excluded (start) , Included (end)) | (Excluded (start) , Excluded (end)) => start < end , (Included (start) , Included (end)) => start <= end , } } }}}
mkitem!{mktrait!{# [doc = " Used to convert a range into start and end bounds, consuming the"] # [doc = " range by value."] # [doc = ""] # [doc = " `IntoBounds` is implemented by Rust’s built-in range types, produced"] # [doc = " by range syntax like `..`, `a..`, `..b`, `..=c`, `d..e`, or `f..=g`."] # [unstable (feature = "range_into_bounds" , issue = "136903")] pub trait IntoBounds < T > : RangeBounds < T > { # [doc = " Convert this range into the start and end bounds."] # [doc = " Returns `(start_bound, end_bound)`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " #![feature(range_into_bounds)]"] # [doc = " use std::ops::Bound::*;"] # [doc = " use std::ops::IntoBounds;"] # [doc = ""] # [doc = " assert_eq!((0..5).into_bounds(), (Included(0), Excluded(5)));"] # [doc = " assert_eq!((..=7).into_bounds(), (Unbounded, Included(7)));"] # [doc = " ```"] fn into_bounds (self) -> (Bound < T > , Bound < T >) ; # [doc = " Compute the intersection of  `self` and `other`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " #![feature(range_into_bounds)]"] # [doc = " use std::ops::Bound::*;"] # [doc = " use std::ops::IntoBounds;"] # [doc = ""] # [doc = " assert_eq!((3..).intersect(..5), (Included(3), Excluded(5)));"] # [doc = " assert_eq!((-12..387).intersect(0..256), (Included(0), Excluded(256)));"] # [doc = " assert_eq!((1..5).intersect(..), (Included(1), Excluded(5)));"] # [doc = " assert_eq!((1..=9).intersect(0..10), (Included(1), Included(9)));"] # [doc = " assert_eq!((7..=13).intersect(8..13), (Included(8), Excluded(13)));"] # [doc = " ```"] # [doc = ""] # [doc = " Combine with `is_empty` to determine if two ranges overlap."] # [doc = ""] # [doc = " ```"] # [doc = " #![feature(range_into_bounds)]"] # [doc = " #![feature(range_bounds_is_empty)]"] # [doc = " use std::ops::{RangeBounds, IntoBounds};"] # [doc = ""] # [doc = " assert!(!(3..).intersect(..5).is_empty());"] # [doc = " assert!(!(-12..387).intersect(0..256).is_empty());"] # [doc = " assert!((1..5).intersect(6..).is_empty());"] # [doc = " ```"] fn intersect < R > (self , other : R) -> (Bound < T > , Bound < T >) where Self : Sized , T : Ord , R : Sized + IntoBounds < T > , { let (self_start , self_end) = IntoBounds :: into_bounds (self) ; let (other_start , other_end) = IntoBounds :: into_bounds (other) ; let start = match (self_start , other_start) { (Included (a) , Included (b)) => Included (Ord :: max (a , b)) , (Excluded (a) , Excluded (b)) => Excluded (Ord :: max (a , b)) , (Unbounded , Unbounded) => Unbounded , (x , Unbounded) | (Unbounded , x) => x , (Included (i) , Excluded (e)) | (Excluded (e) , Included (i)) => { if i > e { Included (i) } else { Excluded (e) } } } ; let end = match (self_end , other_end) { (Included (a) , Included (b)) => Included (Ord :: min (a , b)) , (Excluded (a) , Excluded (b)) => Excluded (Ord :: min (a , b)) , (Unbounded , Unbounded) => Unbounded , (x , Unbounded) | (Unbounded , x) => x , (Included (i) , Excluded (e)) | (Excluded (e) , Included (i)) => { if i < e { Included (i) } else { Excluded (e) } } } ; (start , end) } }}}
